    generate_all,
});

use crate::aap::caps::state_read;

struct Node;

fn parse_json_strings(s: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c == '"' {
            let mut cur = String::new();
            while let Some(d) = chars.next() {
                match d {
                    '"' => break,
                    '\\' => {
                        if let Some(e) = chars.next() {
                            match e {
                                'n' => cur.push('\n'),
                                't' => cur.push('\t'),
                                'r' => cur.push('\r'),
                                other => cur.push(other),
                            }
                        }
                    }
                    _ => cur.push(d),
                }
            }
            out.push(cur);
        }
    }
    out
}

fn parse(raw: &str) -> Vec<String> {
    let t = raw.trim();
    let items: Vec<String> = if t.starts_with('[') {
        parse_json_strings(t)
    } else {
        t.split(|c: char| c == '\n' || c == ',' || c.is_whitespace())
            .map(|l| l.to_string())
            .collect()
    };
    items
        .into_iter()
        .map(|l| l.trim().to_string())
        .filter(|l| !l.is_empty())
        .collect()
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        for key in ["urls", "subscriptions", "feeds"] {
            if let Some(raw) = state_read::get(key) {
                let urls = parse(&raw);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        SubscriptionList { urls: Vec::new() }
    }
}

export!(Node);
